        case HB_IR_XGETBV: {
            emit_mov_reg(buf, 0, 19);
            emit_call_helper(buf, (void*)hb_jit_helper_xgetbv);
            return HB_OK;
        }

        case HB_IR_VERR:
        case HB_IR_VERW:
        case HB_IR_RDTSC:
        case HB_IR_RDTSCP:
            /* MacRunner 2026-08-15, лейн ЛЕСТНИЦА, итерация 938 — ЧЕРЕЗ ИСПОЛНИТЕЛЬ, а не
             * своим помощником. Соседний `XGETBV` показывает, чем кончается второй экземпляр
             * семантики: в 531 помощник отдавал `0x3` безусловно, интерпретатор — `0x7` в 64
             * битах, и гость получал РАЗНЫЙ ответ в зависимости от того, кто исполнил.
             * У счётчика тактов расхождение было бы ещё злее: время шло бы с двумя разными
             * началами отсчёта в одном прогоне. Одна копия семантики — одно поведение.
             * И это же снимает грабли 910: правка, проверенная только интерпретатором. */
            return emit_interp_ir_helper(buf, instr);

