                perepis_uchest(buf, 0, instr->src1.size, SH_NATIV_XMM);
                emit_direct_mem_addr(buf, &instr->src1);
                emit_direct_mem128_load_to_x20_x22(buf);
                emit_store_x20_x22_to_xmm(buf, instr->dst.reg);
