    if (r != HB_OK) { ctx->last_result = r; return; }
    r = hb_jit_helper_read_u64_fast(ctx, table, &base);
    if (r != HB_OK) { ctx->last_result = r; return; }
    r = hb_jit_read_guest_u64_result(ctx, rsp, &ret_addr);
    if (r != HB_OK) { ctx->last_result = r; return; }

