            eax = bits;
            r9 += ecx;
            ecx = edx - 2u;
            eax >>= (ecx & 31u);
            ecx = edx;
            eax &= 3u;
            edx += 4u;
            eax++;
            r10 += eax;
            eax = bits;
            eax >>= (ecx & 31u);
            eax &= 3u;
            eax++;
