    if (!ctx || !instr) return;
    if (hb_flags_eval_cond(ctx, (hb_cc_t)cc, &value) != HB_OK) return;
    /* Итерация 359: при ложном условии приёмник всё равно записывается — см. соседний
     * `hb_jit_helper_exec_cmovcc_lazy`. Источником тогда служит сам приёмник. */
