static bool block_has_ucrt_sse2_memmove_entry_signature(hb_context_t* ctx,
                                                        const hb_ir_block_t* block) {
    static const uint8_t sig[] = {
        0x56,                   /* push rsi */
        0x57,                   /* push rdi */
        0x48, 0x89, 0xcf,       /* mov rdi, rcx */
        0x48, 0x89, 0xd6,       /* mov rsi, rdx */
        0x49, 0x89, 0xf9,       /* mov r9, rdi */
        0x49, 0x29, 0xf1,       /* sub r9, rsi */
        0x4d, 0x39, 0xc1,       /* cmp r9, r8 */
        0x0f, 0x82,             /* jb copy_bwd */
        0x00, 0x00, 0x00, 0x00, /* rel32 wildcard */
        0x49, 0x83, 0xf8, 0x04, /* cmp r8, 4 */
        0x0f, 0x82              /* jb copy_fwd3 */
    };
    if (!ctx || !ctx->memory || !block || block->instr_count < 8) return false;
    if (block->instrs[0].op != HB_IR_PUSH || block->instrs[1].op != HB_IR_PUSH ||
        block->instrs[2].op != HB_IR_MOV || block->instrs[3].op != HB_IR_MOV ||
        block->instrs[4].op != HB_IR_MOV || block->instrs[5].op != HB_IR_SUB ||
        block->instrs[6].op != HB_IR_CMP || block->instrs[7].op != HB_IR_Jcc)
        return false;
    for (size_t i = 0; i < sizeof(sig); i++) {
        uint8_t b = 0;
        if (i >= 19 && i <= 22) continue;
        if (hb_memory_read_u8(ctx->memory, block->guest_addr + i, &b) != HB_OK)
            return false;
        if (b != sig[i]) return false;
    }
    return true;
}

static bool emit_native_memmove_entry_guard(hb_codegen_buffer_t* out,
                                            hb_context_t* ctx,
                                            const hb_ir_block_t* block) {
    size_t fallback_branch;
    if (!out || out->arch == HB_ARCH_X86 || !jit_native_memmove_enabled())
        return false;
    if (!block_has_ucrt_sse2_memmove_entry_signature(ctx, block))
        return false;

    emit_mov_reg(out, 0, 19);
    emit_mov_imm64(out, 1, (uint64_t)(uintptr_t)block);
    emit_call_helper(out, (void*)hb_jit_helper_try_native_memmove);
    emit_cmp_imm(out, 0, 0);
    fallback_branch = emit_bcond_deferred(out, 0); /* EQ -> helper declined; run original block */
    emit_epilogue(out);
    patch_bcond(out, fallback_branch, 0, out->size);
    return true;
}

static bool codegen_is_control_transfer_op(hb_ir_op_t op) {
    return op == HB_IR_CALL || op == HB_IR_RET || op == HB_IR_JMP ||
           op == HB_IR_Jcc || op == HB_IR_LOOP || op == HB_IR_JRCXZ;
}


/* Сколько единиц закончились НЕ переходом и потребовали собственной записи pc. */
unsigned long long g_cg_tail_pc_written;
/* Перепись ПРЯМЫХ единиц (без единого перехода) — двумя числами, см.
 * codegen_emit_tail_pc_if_needed. Разность и есть число дефектов класса
 * «единица не объявляет свой выход»; ноль читается как доказательство. */
unsigned long long g_cg_straight_units;
unsigned long long g_cg_straight_units_pc;
/* Из них ушедших БЫСТРЫМ ПУТЁМ-свёрткой — ровно те, у кого записи pc не было
 * до 05.09. Ноль отвечает «дыры не было», ненулевое называет её размер. */
unsigned long long g_cg_straight_units_idiom;

static size_t codegen_instr_limit_before_fallthrough(const hb_ir_block_t* block) {
    if (!block) return 0;
    /* Повторный проход сторожа: предел задан снаружи и не может быть превышен.
     * ★ БЕЗ проверки `g_cg_merge_block == block`: предел считается на :16750, а
     * `g_cg_merge_block` взводится только на :16873, то есть ПОЗЖЕ. С этой проверкой
     * условие всегда ложно, повтор давал тот же код, и сторож срабатывал вхолостую
     * (замер: povtorov=3, падение осталось). Значение потоковое и живёт ровно один
     * повторный вызов — перепутать блоки нечем. */
    if (g_cg_merge_force_limit && g_cg_merge_force_limit < block->instr_count)
        return g_cg_merge_force_limit;
    if (cg_merge_blocks_enabled() && !hb_gate( HB_GATE_HB_MERGE_NO_EXTEND )) {
        for (size_t i = 0; i < block->instr_count; i++) {
            const hb_ir_instr_t* in = &block->instrs[i];
            if (!codegen_is_control_transfer_op(in->op)) continue;
            /* условный переход ВНУТРЬ единицы обрывом не считается */
            { size_t tj = 0;
              if (in->op == HB_IR_Jcc && cg_merge_target_index(block, in->target, &tj) &&
                  cg_merge_skip_ok(i, tj)) continue; }
            return i + 1;
        }
        return block->instr_count;
    }
    for (size_t i = 0; i < block->instr_count; i++) {
        if (codegen_is_control_transfer_op(block->instrs[i].op)) return i + 1;
    }
    return block->instr_count;
}

static hb_result_t hb_arm64_codegen_block_with_cfg_inner(hb_arm64_codegen_t* cg,
                                                         const hb_ir_block_t* block,
                                                         const hb_ir_cfg_t* cfg,
                                                         hb_codegen_buffer_t* out);

/* MacRunner 2026-07-30 — timed wrapper; see hb_contract_telemetry.h. This is the other half of a
 * compile: emitting the code, as opposed to preparing it for the cache. */
/* MacRunner 2026-07-31 — frameless blocks, gated by MACRUNNER_HB_LEAN_FRAME.
 *
 * 48.3 % of blocks contain no call, yet every block pays a 6-register callee-saved frame: 12 memory accesses
 * per dispatch on blocks averaging 3.14 guest instructions. Measured over 1 096 350 real blocks, eliding it on
 * call-free blocks removes 6 352 164 memory accesses and 11.2 % of all emitted code — 1.87x the entire
 * register-allocation ceiling.
 *
 * Whether a block calls is known only after lowering, so emit optimistically in lean mode and re-emit with the
 * frame if a call appeared. Codegen is 2.2 us/block (0.69 s per run, already measured and refuted as a cost),
 * so redoing ~52 % of blocks is ~0.35 s. */
static int lean_frame_enabled(void) {
    const char* e = hb_gate( HB_GATE_HB_LEAN_FRAME );
    const char* r = hb_gate( HB_GATE_HB_LEAN_REMAP_ONLY );
    int cached = (e && *e && *e != '0') || (r && *r && *r != '0');
    return cached;
}

/* Bisect half A: apply the register remap but STILL emit the frame. That is semantically valid — the block
 * preserves callee-saved registers it has stopped using — so if this boots, the remap is innocent and the
 * defect is in dropping the frame; if it breaks, the remap itself is at fault. */
static int lean_remap_only(void) {
    const char* e = hb_gate( HB_GATE_HB_LEAN_REMAP_ONLY );
    int cached = e && *e && *e != '0';
    return cached;
}

/* x19->x9 .. x23->x13: five scratch registers into the caller-saved bank, which no callee must preserve.
 * x0-x8 argument usage is untouched. */
static void lean_frame_arm(hb_codegen_buffer_t* out) {
    int i;
    for (i = 0; i < 32; i++) out->rmap[i] = (uint8_t)i;
    /* x9 and x10 are NOT free: hb_arm64_codegen.c already emits `MOV x9, x20` / `MOV x10, x21` in a fast
     * path, so mapping x19->x9 made that instruction overwrite the ctx pointer and killed the guest at once
     * (22 blocks translated, no markers). Use x11-x15, the five caller-saved registers nothing else claims. */
    out->rmap[19] = 11; out->rmap[20] = 12; out->rmap[21] = 13;
    out->rmap[22] = 14; out->rmap[23] = 15;
    out->rmap_active = HB_RMAP_ARMED;
    out->emitted_call = 0;
    g_lean_frame_on = 1;
    if (lean_remap_only()) g_lean_remap_only = 1;
}

/* ★ ОБЁРТКА РАДИ ЗАМЫКАНИЯ ОТЛОЖЕННЫХ ПЕРЕХОДОВ К ОБЩЕМУ ЭПИЛОГУ.
 *
 * Тело эпилога теперь достаётся ЧАСТОМУ пути (обычному выходу блока), а редкий путь отказа
 * помощника откладывает переход вперёд. Незамкнутый переход вперёд — БИТЫЙ КОД, а блок может
 * уйти через инлайн-кеш или сцепление, минуя обычный эпилог. У рабочей функции около десятка
 * мест возврата; дописывать замыкание в каждое — ровно тот способ, которым в этом лейне уже
 * дважды получались дыры. Обёртка закрывает их ВСЕ одним местом.
 *
 * Имя `_inner` в файле уже занято (повторная попытка кодогенерации), поэтому `_noclose`. */
static hb_result_t hb_arm64_codegen_block_with_cfg_noclose(hb_arm64_codegen_t* cg,
                                            const hb_ir_block_t* block,
                                            const hb_ir_cfg_t* cfg, hb_codegen_buffer_t* out);

hb_result_t hb_arm64_codegen_block_with_cfg(hb_arm64_codegen_t* cg, const hb_ir_block_t* block,
                                            const hb_ir_cfg_t* cfg, hb_codegen_buffer_t* out) {
    size_t reloc0 = out ? out->reloc_count : 0;
    hb_result_t r = hb_arm64_codegen_block_with_cfg_noclose(cg, block, cfg, out);
    /* Разбор мёртвых записей ленивых флагов (итерация 156, снятие — 160). Место выбрано
     * ЗДЕСЬ, а не в `_noclose`: у того две ветви (бережливый кадр возвращается раньше), и
     * счёт в одной из них молча пропускал бы вторую — ровно та дыра, из-за которой в этом
     * файле и заведена обёртка. */
    if (r == HB_OK && out && (deadlazy_count_enabled() || deadlazy_skip_enabled())) {
        deadlazy_scan(out);
        if (deadlazy_skip_enabled() && out->deadlazy_marked) {
            /* ★ ВТОРОЙ ПРОХОД. Сброс повторяет тот, которым пользуется закрепление
             * (:15526): размер, релокации, признак вызова и карта смещений. Отложенный
             * эпилог обнуляется прологом при каждом выпуске, поэтому его здесь нет. */
            uint64_t keep[8];
            memcpy(keep, out->deadlazy_skip, sizeof(keep));
            out->size = 0;
            out->reloc_count = reloc0;
            out->reloc_overflow = false;
            out->emitted_call = 0;
            out->host_off_count = 0;
            out->host_off_overflow = false;
            g_deadlazy_apply = 1;
            g_deadlazy_mask = keep;
            r = hb_arm64_codegen_block_with_cfg_noclose(cg, block, cfg, out);
            g_deadlazy_apply = 0;
            g_deadlazy_mask = NULL;
            g_deadlazy_reemit++;
        }
        /* ★ ПЕЧАТЬ СТОИТ ЗДЕСЬ, А НЕ В `deadlazy_scan` (итерация 174).
         *
         * Прежде она стояла в конце разбора, то есть ДО того, как обёртка увеличит
         * `g_deadlazy_reemit`. На блоке, где срабатывал период, счётчик переизданий отставал
         * ровно на единицу, и сумма гистограммы расходилась с ним на 1 — на одном корпусе
         * расхождение было, на другом (там период попал на непомеченный блок) нет.
         * Это была не ошибка учёта, а ошибка МЕСТА печати: она показывала два счётчика,
         * снятых в разные моменты. */
        if ((g_deadlazy_blocks % 250) == 0)
            fprintf(stderr, "macrunner-hb-deadlazy: блоков=%llu записей=%llu мёртвых=%llu (%.2f%%) "
                            "команд-под-снятие=%llu слов-не-меньше=%llu блоков-переизданных=%llu"
                            "  помечено-в-блоке 1:%llu 2:%llu 3:%llu 4+:%llu\n",
                    (unsigned long long)g_deadlazy_blocks, (unsigned long long)g_deadlazy_stores,
                    (unsigned long long)g_deadlazy_dead,
                    g_deadlazy_stores ? 100.0 * (double)g_deadlazy_dead / (double)g_deadlazy_stores : 0.0,
                    (unsigned long long)g_deadlazy_instr, (unsigned long long)g_deadlazy_words,
                    (unsigned long long)g_deadlazy_reemit,
                    (unsigned long long)g_deadlazy_hist[0], (unsigned long long)g_deadlazy_hist[1],
                    (unsigned long long)g_deadlazy_hist[2], (unsigned long long)g_deadlazy_hist[3]);
    }
    epi_close_pending(out);
    if (r == HB_OK) g_cg_emit_instrs += (unsigned long long)g_cg_last_instrs;
    return r;
}

/* MacRunner 2026-08-24, лейн КАДР — ПЕЧАТЬ ДОЛИ ПО ЗАВЕРШЕНИЮ, а не по периоду.
 *
 * Период был 20 000 попыток при 5073 разных блоках на стенде i386 и 52 записях на x64.
 * Проверено по шести журналам лейна: строка `macrunner-hb-lean-frame` не напечаталась
 * НИ РАЗУ, то есть заходы 1 и 2 шли с включённым бережливым кадром вслепую. Период
 * оставлен как есть (он полезен на длинных прогонах), добавлен безусловный вывод на
 * выходе — он от размера корпуса не зависит. Образец — hb_emit_map_atexit (:8228). */
static void lean_frame_atexit(void) {
    if (!g_lean_attempts) return;
    fprintf(stderr,
            "macrunner-hb-lean-frame-итог: попыток=%llu применено=%llu (%.2f %%) переведено-заново=%llu\n",
            (unsigned long long)g_lean_attempts, (unsigned long long)g_lean_kept,
            100.0 * (double)g_lean_kept / (double)g_lean_attempts,
            (unsigned long long)g_lean_retried);
    fflush(stderr);
}

static hb_result_t hb_arm64_codegen_block_with_cfg_noclose(hb_arm64_codegen_t* cg,
                                            const hb_ir_block_t* block,
                                            const hb_ir_cfg_t* cfg, hb_codegen_buffer_t* out) {
    struct timespec a, b;
    hb_result_t r;
    clock_gettime(CLOCK_MONOTONIC, &a);
    if (lean_frame_enabled() && out && out->size == 0) {
        size_t reloc0 = out->reloc_count;
        out->sra_mask = 0;   /* необнулённый буфер — см. ниже */
        lean_frame_arm(out);
        g_cg_merge_need_limit = 0;
        g_cg_merge_force_limit = 0;
        r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
        if (!g_lean_attempts) atexit(lean_frame_atexit);   /* итог по выходу, лейн КАДР */
        g_lean_attempts++;
        if (r != HB_OK || out->emitted_call) {
            g_lean_retried++;
            out->size = 0;
            out->reloc_count = reloc0;
            out->reloc_overflow = false;
            out->rmap_active = 0;
            out->emitted_call = 0;
            g_cg_merge_need_limit = 0;
            r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
        }
        else g_lean_kept++;
        /* ★ СТОРОЖ СРАЩЁННОГО ПЕРЕХОДА и на пути БЕРЕЖЛИВОГО КАДРА.
         * Замер 25.08: LEAN_FRAME=1 один — exit=0, MERGE_BLOCKS=1 один — exit=0,
         * ВМЕСТЕ — exit=37. Причина та же, что в основном пути; там сторож стоял,
         * здесь его не было. Копия того же отката. */
        if (r == HB_OK && out && g_cg_merge_need_limit) {
            g_cg_merge_force_limit = g_cg_merge_need_limit;
            g_cg_merge_need_limit = 0;
            out->size = 0;
            out->reloc_count = reloc0;
            out->reloc_overflow = false;
            out->emitted_call = 0;
            out->host_off_count = 0;
            out->rmap_active = 0;
            r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
            g_cg_merge_force_limit = 0;
        }
        if (g_lean_attempts && (g_lean_attempts % 20000) == 0)
            fprintf(stderr, "macrunner-hb-lean-frame: попыток=%llu применено=%llu (%.1f%%) переведено-заново=%llu\n",
                    g_lean_attempts, g_lean_kept,
                    100.0 * (double)g_lean_kept / (double)g_lean_attempts, g_lean_retried);
        out->rmap_active = 0;
        clock_gettime(CLOCK_MONOTONIC, &b);
        hb_contract_telemetry_add_time(0, (uint64_t)(b.tv_sec - a.tv_sec) * 1000000000ull
                                          + (uint64_t)b.tv_nsec - (uint64_t)a.tv_nsec);
        return r;
    }
    {
        size_t reloc0 = out ? out->reloc_count : 0;
        /* ★ ЯВНОЕ ОБНУЛЕНИЕ. hb_codegen_buffer_t в этом дереве нигде не обнуляется целиком —
         * тот же капкан, из-за которого rmap_active получил часовой 0xA5. Непрочитанный
         * мусор в маске включил бы закрепление вслепую. */
        if (out) {
            out->sra_mask = 0;
            /* Буфер в этом дереве нигде не обнуляется целиком — счётчики надо занулить явно,
             * иначе первый блок посчитает мусор со стека. Защита по откату размера — вторая
             * линия, а не первая. */
            out->sra_cnt_size = 0;
            memset(out->sra_cnt_n, 0, sizeof(out->sra_cnt_n));
            memset(out->sra_cnt_wr, 0, sizeof(out->sra_cnt_wr));
            memset(out->sra_cnt_seg_used, 0, sizeof(out->sra_cnt_seg_used));
            memset(out->sra_cnt_seg_written, 0, sizeof(out->sra_cnt_seg_written));
            out->sra_cnt_seg = 0;
            out->sra_cnt_overflow = 0;
            out->sra_slot_ready = 0;
        }
        g_cg_merge_need_limit = 0;
        g_cg_merge_force_limit = 0;
        r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
        /* ★ СТОРОЖ СРАЩЁННОГО ПЕРЕХОДА: перевести заново с обрезанным пределом. */
        if (r == HB_OK && out && g_cg_merge_need_limit) {
            g_cg_merge_force_limit = g_cg_merge_need_limit;
            g_cg_merge_need_limit = 0;
            out->size = 0;
            out->reloc_count = reloc0;
            out->reloc_overflow = false;
            out->emitted_call = 0;
            out->host_off_count = 0;
            r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
            g_cg_merge_force_limit = 0;
            {   static uint64_t said;
                if (++said <= 3 || (said & 0xffful) == 0)
                    fprintf(stderr, "macrunner-edinica-guard: povtorov=%llu (srashchennyi perehod v predele)\n",
                            (unsigned long long)__atomic_load_n(&g_cg_merge_guard_hits, __ATOMIC_RELAXED)),
                    fflush(stderr); }
        }
        /* Второй проход: набор выбран по ФАКТИЧЕСКИ выпущенному коду первого прохода.
         * Выпускаем заново только если есть что закреплять — блоков без выгодного регистра
         * большинство, и им второй проход не платится. */
        if (r == HB_OK && out && sra_enabled() &&
            (out->arch == HB_ARCH_X64 || (out->arch == HB_ARCH_X86 && sra_i386_enabled()))) {
            /* ★ БАНК СНИМАЕТСЯ ДО СБРОСА `emitted_call`. Признак «зовёт помощника»
             * принадлежит ПЕРВОМУ проходу; после сброса он всегда 0, и банк бы всегда
             * выходил caller-saved — то есть блок с вызовом получил бы регистры, которые
             * помощник затирает. Порядок здесь не косметика. */
            uint8_t bank = sra_bank_for(out);
            uint16_t mask;
            sra_count(SRA_C_CONSIDERED);
            out->sra_bank = bank;
            {   /* Итоги уже набраны ПРИ ВЫПУСКЕ — прохода по буферу нет.
                 * Сличитель `MACRUNNER_HB_SRA_VERIFY_COUNTS=1` гоняет и прежний проход, и
                 * сравнивает: замена дорогого пути дешёвым обязана быть ДОКАЗАНА, а не
                 * объявлена. */
                unsigned k, seg_n = (unsigned)(out->sra_cnt_overflow ? 0
                                               : out->sra_cnt_seg + 1u);
                for (k = 0; k < seg_n; k++) {
                    uint16_t later = 0; unsigned q;
                    for (q = k + 1; q < seg_n; q++) later |= out->sra_cnt_seg_used[q];
                    out->sra_reload_after[k] = later;
                    out->sra_seg_written[k] = out->sra_cnt_seg_written[k];
                }
                out->sra_seg_count = (uint8_t)seg_n;
                out->sra_call_index = 0;
                sra_count(seg_n ? SRA_C_SEG_MARKED : SRA_C_SEG_ROUGH);
                mask = sra_select_from_code(out, out->sra_cnt_n, out->sra_cnt_wr,
                                            (unsigned)out->sra_cnt_seg);
                if (sra_verify_counts()) {
                    {
                        unsigned n2[HB_REG_RIP], w2[HB_REG_RIP], nc2;
                        uint8_t seg_keep = out->sra_seg_count;
                        uint16_t rl_keep[HB_SRA_MAX_SEGMENTS], sw_keep[HB_SRA_MAX_SEGMENTS];
                        uint16_t mask2;
                        memcpy(rl_keep, out->sra_reload_after, sizeof(rl_keep));
                        memcpy(sw_keep, out->sra_seg_written, sizeof(sw_keep));
                        sra_mark_segments(out, n2, w2, &nc2);
                        mask2 = sra_select_from_code(out, n2, w2, nc2);
                        if (mask2 != mask || memcmp(rl_keep, out->sra_reload_after,
                                                    sizeof(rl_keep)) ||
                            memcmp(sw_keep, out->sra_seg_written, sizeof(sw_keep)) ||
                            seg_keep != out->sra_seg_count) {
                            g_sra_count_mismatch++;
                            if (g_sra_count_mismatch <= 8)
                                fprintf(stderr, "macrunner-hb-sra-счёт-РАСХОДИТСЯ: блок=0x%llx "
                                        "маска %u против %u, отрезков %u против %u\n",
                                        (unsigned long long)block->guest_addr,
                                        (unsigned)mask, (unsigned)mask2,
                                        (unsigned)seg_keep, (unsigned)out->sra_seg_count);
                        }
                        mask = mask2;   /* при сличении верим ПРОХОДУ, он эталон */
                        out->sra_call_index = 0;
                    }
                }
            }
            /* ★ БЛОКИ С ВЫЗОВАМИ ПОКА НЕ ЗАКРЕПЛЯЕМ. Помощник получает `ctx` и вправе САМ
             * писать регистр гостя в память (`hb_jit_helper_load_to_reg_sized` делает ровно
             * это). Такая запись НЕ видна ни одному `str` в выпущенном коде, то есть счёт
             * первого прохода её не заметит, а закреплённый регистр молча разойдётся с
             * памятью. Пока вокруг вызова нет выгрузки и перечитывания — не закрепляем.
             * Гейт `MACRUNNER_HB_STATIC_REGS_CALLS=1` снимает запрет для замеров. */
            /* Запрет на блоки с вызовами СНЯТ: связность вокруг вызова заведена, цена
             * вызовов учтена в отборе. Гейт остаётся, чтобы можно было сравнить руки. */
            /* ★ ВЕТО ПО ОТКАЗУ — см. sra_block_can_fault. Признак берётся из выпущенного
             * кода первого прохода, а не из набора гейтов. */
            /* ★ ВЕТО ПО ОТКАЗУ — БЕЗУСЛОВНО с 05.09.2026.
             * Замером установлено: 18,4 % блоков без вызовов всё же трогают гостевую память и
             * могут отказать. Пока путь отказа откатывал состояние гостя к снимку до блока,
             * потерянный грязный регистр отбрасывался вместе со всем остальным, и вето
             * включалось только под тремя гейтами «без отката». Снимок удалён: отката нет
             * никогда, отказ разрешается ТОЧНОЙ ПОЗИЦИЕЙ и состоянием в `ctx` — а грязный
             * закреплённый регистр в `ctx` не выгружен. Поэтому блок, способный отказать,
             * не закрепляется вовсе. Цена известна из первой редакции вето: 54,4 % выигрыша
             * закрепления (0,59 % → 0,27 %); выгрузка перед отказоспособным обращением —
             * отдельная работа, если закрепление вообще станет умолчанием. */
            if (mask && sra_block_can_fault(out)) {
                mask = 0; g_sra_fault_veto++; sra_count(SRA_C_VETO_FAULT);
            }
            if (!mask) sra_count(SRA_C_MASK_EMPTY);
            else sra_count(bank == HB_SRA_BANK_SCRATCH ? SRA_C_BANK_SCRATCH : SRA_C_BANK_SAVED);
            if (mask) {
                out->size = 0;
                out->reloc_count = reloc0;
                out->reloc_overflow = false;
                out->emitted_call = 0;
                out->host_off_count = 0;
                out->host_off_overflow = false;
                out->sra_bank = bank;
                out->sra_mask = mask;
                out->sra_call_index = 0;
                r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
                /* ★ СТОРОЖ, А НЕ ДОПУЩЕНИЕ. Банк caller-saved держится на том, что блок
                 * никого не зовёт. Если второй проход всё-таки выпустил вызов, значения
                 * гостя пропали бы молча — поэтому выпускаем ЗАНОВО без закрепления. */
                if (r == HB_OK && bank == HB_SRA_BANK_SCRATCH && out->emitted_call) {
                    g_sra_bank_veto++; sra_count(SRA_C_VETO_BANK);
                    if (g_sra_bank_veto <= 8)
                        fprintf(stderr, "macrunner-hb-sra: блок=0x%llx второй проход выпустил "
                                        "вызов при банке caller-saved — закрепление снято\n",
                                (unsigned long long)block->guest_addr);
                    out->size = 0;
                    out->reloc_count = reloc0;
                    out->reloc_overflow = false;
                    out->emitted_call = 0;
                    out->host_off_count = 0;
                    out->host_off_overflow = false;
                    out->sra_mask = 0;
                    r = hb_arm64_codegen_block_with_cfg_inner(cg, block, cfg, out);
                } else {
                    g_sra_blocks_pinned++;
                    if (bank == HB_SRA_BANK_SCRATCH) g_sra_blocks_scratch++;
                }
            }
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &b);
    hb_contract_telemetry_add_time(0, (uint64_t)(b.tv_sec - a.tv_sec) * 1000000000ull
                                      + (uint64_t)b.tv_nsec - (uint64_t)a.tv_nsec);
    return r;
}

/* ═══ БЫСТРЫЕ ПУТИ-ИДИОМЫ: ОДИН ОТВЕТ, НИ ОДНОГО ВЫХОДА ═══
 *
 * Свёртки ТОЛЬКО выпускают тело и отвечают «да». Ни эпилога, ни возврата из
 * выпуска единицы здесь нет — это делает вызывающий, в одном месте. Смысл в том,
 * чтобы выход из единицы был ОДИН: всё, что обязано случиться на выходе (сегодня
 * это запись гостевого pc), дописывается туда однажды и покрывает все свёртки
 * разом, включая те, которых ещё нет. */
static bool codegen_try_idiom_block(hb_codegen_buffer_t* out,
                                    hb_arm64_codegen_t* cg,
                                    const hb_ir_cfg_t* cfg,
                                    const hb_ir_block_t* block,
                                    bool mid_block_transfer) {
    if (mid_block_transfer) return false;
    if (block->instr_count == 7 && emit_unity_sort_inner_loop(out, block)) return true;
    if (cfg && block->instr_count == 5) {
        const hb_ir_instr_t* jcc = &block->instrs[4];
        const hb_ir_block_t* guard = (jcc->op == HB_IR_Jcc)
            ? find_cfg_block_for_codegen(cfg, jcc->guest_addr + jcc->guest_len)
            : NULL;
        if (emit_copy_scan_counted_loop_block(out, block, guard)) return true;
    }
    if (emit_unity_freelist_fill_loop(out, block)) return true;
    if (emit_unity_u32_ptr_compare(out, block)) return true;
    if (emit_mono_string_hash(out, cg, block)) return true;
    if (emit_mono_string_equal(out, cg, block)) return true;
    if (emit_mono_metadata_coded_index_search(out, cg, block)) return true;
    if (emit_mono_metadata_rowptr_entry(out, cg, block)) return true;
    if (emit_mono_metadata_decode_row_entry(out, cg, block)) return true;
    if (emit_mono_metadata_decode_col(out, cg, block)) return true;
    if (emit_mono_metadata_decode_row_loop(out, cg, block)) return true;
    if (emit_mono_metadata_bsearch_loop(out, cg, block)) return true;
    if (emit_unity_string_bsearch_loop(out, block)) return true;
    if (!jit_direct_mem_codegen_enabled(out) && emit_hot_helper_block(out, block)) return true;
    if (emit_store_count_loop_block(out, block)) return true;
    if (emit_prologue_local_init_test_block(out, block)) return true;
    if (emit_epilogue_restore_ret_block(out, block)) return true;
    if (emit_zero_store_update_backedge_block(out, block)) return true;
    if (emit_copy_scan_body_block(out, block)) return true;
    if (emit_hot_scalar_scan_loop(out, block)) return true;
    if (emit_zero_test_jcc_block(out, block)) return true;
    return false;
}

/* «Прямая единица» — блок БЕЗ единого перехода. Именно она не пишет гостевой pc
 * сама (писать его было некому: за неё это делал диспетчер на C, а сцепление в
 * диспетчер не возвращается) и именно её цепочка исполняла ДВАЖДЫ. Считается
 * своим предикатом кодогенератора, чтобы перепись и условие записи не могли
 * разойтись определением. */
static bool codegen_block_is_straight(const hb_ir_block_t* block) {
    size_t i;
    if (!block) return false;
    for (i = 0; i < block->instr_count; i++)
        if (codegen_is_control_transfer_op(block->instrs[i].op)) return false;
    return block->instr_count != 0;
}

/* ★★★★★★★ ЕДИНСТВЕННАЯ ТОЧКА, ГДЕ ЕДИНИЦА ОБЪЯВЛЯЕТ СВОЙ ВЫХОД.
 *
 * Выпущенная единица обязана оставлять гостевой pc ТОЧНЫМ САМА — тот же инвариант,
 * что держат эталоны (QEMU обновляет cpu_pc на выходе КАЖДОГО TB). Без него
 * сцепление неверно ПО ПОСТРОЕНИЮ: цепочка не возвращается в диспетчер, а значит
 * ветвь «Sequential block end» в hb_runtime.c за единицу больше ничего не чинит.
 *
 * ★★ ЧЕРЕЗ emit_set_pc_imm64, А НЕ emit_mov_imm64 — И ЭТО НЕ СТИЛЬ.
 * emit_mov_imm64 ЗАПИСЫВАЕТ УКЛАДКУ В ТАБЛИЦУ ПОЧИНКИ (codegen_note_reloc; x20
 * покрыт). Постоянный кеш при подъёме блока правит такие места как адреса ХОЗЯИНА —
 * а здесь лежит гостевой pc. Замер: приёмка 491/2 -> 439/223, ctx->pc получал адреса
 * хозяйского стека (0x16d1c9f78) и прогон умирал «branch target block not found».
 * emit_set_pc_imm64 кладёт значение КОМПАКТНОЙ укладкой (emit_mov_imm_compact),
 * которая в таблицу починки не пишет.
 *
 * ПЕРЕПИСЬ — ДВУМЯ ЧИСЛАМИ, А НЕ ОДНИМ. `прямых_единиц` считает, сколько прямых
 * единиц вообще прошло выпуск, `из_них_с_pc` — скольким запись досталась. Одно
 * число не различало бы «таких единиц не встретилось» и «запись не сработала», а
 * это разные вещи, и правило про молчащий прибор записано отдельно. Разность двух
 * чисел И ЕСТЬ число дефектов класса; ноль читается как доказательство, а не как
 * тишина. */
static void codegen_emit_tail_pc_if_needed(hb_codegen_buffer_t* out,
                                           const hb_ir_block_t* block,
                                           size_t instr_limit) {
    bool straight;
    if (!out || !block) return;
    straight = codegen_block_is_straight(block);
    if (instr_limit > 0 && instr_limit <= block->instr_count &&
        !codegen_is_control_transfer_op(block->instrs[instr_limit - 1].op)) {
        const hb_ir_instr_t* last = &block->instrs[instr_limit - 1];
        emit_set_pc_imm64(out, last->guest_addr + last->guest_len);
        __atomic_add_fetch(&g_cg_tail_pc_written, 1, __ATOMIC_RELAXED);
        if (straight) __atomic_add_fetch(&g_cg_straight_units_pc, 1, __ATOMIC_RELAXED);
    }
}

static hb_result_t hb_arm64_codegen_block_with_cfg_inner(hb_arm64_codegen_t* cg,
                                                         const hb_ir_block_t* block,
                                                         const hb_ir_cfg_t* cfg,
                                                         hb_codegen_buffer_t* out) {
    size_t instr_limit;
    bool mid_block_transfer;

    if (!block || !out) return HB_ERR_INVALID_ARG;
    if (cg && cg->ctx) out->arch = cg->ctx->arch;
    flags_live_invalidate();   /* см. ABA у кеша неподвижной точки */
    flags_graph_invalidate();  /* тот же ABA: блоки переиспользуют адреса */
    g_cg_acfg = cfg ? cfg->acfg : NULL;
    instr_limit = codegen_instr_limit_before_fallthrough(block);
    mid_block_transfer = instr_limit < block->instr_count;
    /* ★ ПЕРЕПИСЬ СЧИТАЕТСЯ НА ВХОДЕ, А НЕ У МЕСТА ЗАПИСИ — И ЭТО ГЛАВНОЕ В НЕЙ.
     * Счёт у места записи был бы тавтологией: там условие «блок прямой» и условие
     * «писать pc» совпадают, разность выходила бы нулём при ЛЮБОМ числе выходов,
     * включая забытый. Счёт на ВХОДЕ ловит именно то, ради чего заведён: прямую
     * единицу, ушедшую из выпуска мимо записи, каким угодно путём — сегодняшним,
     * завтрашним, ошибочным. Отказ выпуска ниже перепись СНИМАЕТ (блок не будет
     * исполняться, дефектом это не является). */
    if (codegen_block_is_straight(block))
        __atomic_add_fetch(&g_cg_straight_units, 1, __ATOMIC_RELAXED);
    /* Набор закрепления выбирается ЗДЕСЬ, до пролога: пролог его только исполняет, а эпилог
     * читает уже готовым. Считать дважды нельзя — выбор зависит от блока, а эпилог блока не
     * видит; разъехавшиеся пролог и эпилог дали бы несимметричный кадр. */
    /* Первый проход идёт БЕЗ закрепления: набор выбирается по его результату (см.
     * sra_select_from_code) и применяется вторым проходом. Обнуляем явно — буфер могли
     * подать повторно. */
    emit_prologue(out);
    emit_block_counter_accounting(out, (uint32_t)instr_limit);
    emit_native_memmove_entry_guard(out, cg ? cg->ctx : NULL, block);
    {
        uint64_t watch = macrunner_hb_jit_watch_guest_addr();
        if (macrunner_hb_trace_jit_blocks_enabled() && watch && block->guest_addr == watch) {
            fprintf(stderr,
                    "macrunner-hb-codegen-watch: guest=%p instrs=%zu instr_limit=%zu mid=%u unity_sort_candidate=%u\n",
                    (void*)(uintptr_t)block->guest_addr, block->instr_count, instr_limit,
                    mid_block_transfer ? 1u : 0u,
                    unity_sort_inner_loop_candidate(block) ? 1u : 0u);
            fflush(stderr);
        }
    }
    /* ★★★★★★★ 05.09.2026 — БЫСТРЫЕ ПУТИ УХОДЯТ ЧЕРЕЗ ОБЩИЙ ВЫХОД, А НЕ КАЖДЫЙ САМ.
     *
     * Здесь стояла двадцать одна пара строк `emit_epilogue(out); return HB_OK;` —
     * двадцать один выход из выпуска единицы. Всё, что обязано случиться НА ВЫХОДЕ,
     * приходилось бы дописывать двадцать один раз; ровно так теряется запись
     * гостевого pc — она стоит перед ФИНАЛЬНЫМ эпилогом, до которого эти ветви не
     * доходят вовсе. Причина не в забывчивости, а в числе выходов, и убирается
     * причина (правило «заплатка на месте не переносится»).
     *
     * Теперь свёртка только ОТВЕЧАЕТ «я выпустила единицу», а эпилог и запись pc
     * делает вызывающий — в одном месте на обе ветви. Новая свёртка ничего
     * дописывать не обязана: инвариант держится ПО ПОСТРОЕНИЮ, а не по дисциплине.
     * Перепись `прямых_единиц` рядом делает нарушение ЧИСЛОМ, а не падением игры. */
    if (codegen_try_idiom_block(out, cg, cfg, block, mid_block_transfer)) {
        /* ★ ПРЯМАЯ ЕДИНИЦА, УШЕДШАЯ БЫСТРЫМ ПУТЁМ, — ОТДЕЛЬНОЕ ЧИСЛО.
         * До этой правки быстрые пути записи pc не делали ВОВСЕ, и вопрос «была ли
         * там дыра» решался бы чтением двадцати одного предиката-кандидата. Счётчик
         * отвечает замером: ноль означает, что ни одна свёртка прямой единицы не
         * берёт (все они требуют завершителя-перехода), то есть прежний код дыры
         * не имел; не ноль — прямо называет её размер. */
        if (codegen_block_is_straight(block))
            __atomic_add_fetch(&g_cg_straight_units_idiom, 1, __ATOMIC_RELAXED);
        codegen_emit_tail_pc_if_needed(out, block, instr_limit);
        emit_epilogue(out);
        return HB_OK;
    }
    /* ЕДИНИЦА, часть Б: состояние внутренних переходов заводится НА КАЖДЫЙ проход —
     * бережливый кадр выпускает блок дважды, и остатки прошлого прохода дали бы заплату
     * по чужому смещению. */
    g_cg_merge_fix_n = 0;
    g_cg_merge_block = NULL;
    cg_edge_reset();
    /* Перепись рёбер и переполнений заплаты печатается на выходе процесса — регистрируем
     * один раз, БЕЗУСЛОВНО: `patch-range-fail` относится ко всему выпуску, а не к слиянию. */
    { static int rebro_atexit; if (!rebro_atexit) { rebro_atexit = 1; atexit(cg_edge_atexit); } }
    if (cg_merge_blocks_enabled() && block->instr_count <= CG_MERGE_MAX_INSTR) {
        for (size_t k = 0; k < CG_MERGE_MAX_INSTR; k++) g_cg_merge_off[k] = (size_t)-1;
        /* Отметки поглощения — на КАЖДЫЙ проход, как и смещения: бережливый кадр
         * выпускает блок дважды, и остаток прошлого прохода объявил бы корректно
         * завершённым переход, которого в этом проходе нет. */
        memset(g_cg_merge_covered, 0, sizeof(g_cg_merge_covered));
        for (size_t k = 0; k < CG_MERGE_MAX_INSTR; k++) g_cg_merge_pair_off[k] = (size_t)-1;
        g_cg_merge_block = block;
        { static unsigned long armed;
          if (++armed <= 3) {
            fprintf(stderr, "macrunner-edinica-armed: raz=%lu instr_count=%zu\n",
                    armed, block->instr_count); fflush(stderr); } }
    }
    g_cg_last_instrs = instr_limit;
    { size_t emit_size_before = out ? out->size : 0;
    for (size_t i = 0; i < instr_limit; i++) {
        if (g_cg_merge_block == block && out && i < CG_MERGE_MAX_INSTR)
            g_cg_merge_off[i] = out->size;
        /* Решение о живости флагов принимается ЗДЕСЬ: тут известны блок и номер команды,
         * а эмиттеры лежат на двенадцати точках слишком глубоко, чтобы тащить это
         * аргументом. Пара i/i+1 берётся вместе, потому что часть эмиттеров сращивает
         * две команды в одну форму и выпустила бы запись флагов за ВТОРУЮ из них. */
        g_emit_ir++;
        g_lazy_flags_skip = 0;
        /* Решение для СРАЩЁННОЙ пары считается здесь и здесь же обнуляется: у эмиттеров
         * нет ни блока, ни номера команды, а действовать оно обязано ровно один шаг. */
        g_lazy_pair_dead = 0;
        /* ★★★ ПЛАН ВНУТРЕННЕГО РЕБРА — ЗДЕСЬ ЖЕ И ПО ТОЙ ЖЕ ПРИЧИНЕ (лейн ФЛАГИ-2).
         *
         * Считается ДО эмиссии, потому что решают его блок, номер команды и предел
         * выпуска, а у сращивателей нет ни того, ни другого, ни третьего. Годность
         * требует ЧЕТЫРЁХ условий сразу, и каждое проверяется фактом, а не надеждой:
         *   1. следующая команда — именно Jcc (пару берут только такие сращиватели);
         *   2. ПРОВАЛУ ЕСТЬ КУДА ПРОВАЛИВАТЬСЯ: за Jcc в пределах выпуска стоит команда,
         *      и её гостевой адрес РАВЕН адресу проваливания. Без второй половины
         *      проверки «следующая по списку» не значит «следующая по адресу»;
         *   3. цель — начало команды ЭТОЙ единицы и допустима тем же предикатом,
         *      которым предел решает, обрывать ли выпуск (иначе анализ и выпуск
         *      разошлись бы определением);
         *   4. запрет внутреннего прыжка (MERGE_NO_INNER_JUMP) не стоит и место в
         *      таблице фиксаций есть.
         * Само ребро выпускает ХВОСТ пары; здесь только план. */
        cg_edge_reset();
        if (g_cg_merge_block == block && out && cg_merge_fused_edge_enabled() &&
            g_cg_merge_fix_n < CG_MERGE_MAX_INSTR &&
            i + 2 < instr_limit && i + 1 < CG_MERGE_MAX_INSTR &&
            block->instrs[i + 1].op == HB_IR_Jcc &&
            !hb_gate( HB_GATE_HB_MERGE_NO_INNER_JUMP )) {
            const hb_ir_instr_t* jc = &block->instrs[i + 1];
            uint64_t fall = jc->guest_addr + jc->guest_len;
            size_t tj = 0;
            if (block->instrs[i + 2].guest_addr == fall &&
                cg_merge_target_index(block, jc->target, &tj) &&
                cg_merge_skip_ok(i + 1, tj)) {
                g_cg_edge.active = 1;
                g_cg_edge.done = 0;
                g_cg_edge.jcc_i = i + 1;
                g_cg_edge.pair_off = out->size;
                g_cg_edge.target = jc->target;
                g_cg_edge.fallthrough = fall;
                __atomic_add_fetch(&g_cg_edge_planned, 1, __ATOMIC_RELAXED);
            }
        }
        /* Перепись ADC/SBB — считается ДО всякой свёртки, чтобы число не зависело от того,
         * какой эмиттер команду возьмёт. */
        if (block->instrs[i].op == HB_IR_ADC || block->instrs[i].op == HB_IR_SBB) {
            const hb_ir_instr_t* cur = &block->instrs[i];
            HB_PROBE_LOOKED(&pr_adc_perepis);
            if (i > 0) {
                const hb_ir_instr_t* prev = &block->instrs[i - 1];
                bool sootv = (prev->op == HB_IR_ADD || prev->op == HB_IR_SUB) &&
                             !prev->preserve_cf && !cur->preserve_cf &&
                             prev->dst.size == cur->dst.size &&
                             (cur->dst.size == HB_SIZE_32 || cur->dst.size == HB_SIZE_64) &&
                             is_plain_gpr_reg_operand(&prev->dst) &&
                             is_plain_gpr_reg_operand(&cur->dst) &&
                             is_plain_gpr_reg_operand(&cur->src1) &&
                             (cur->src2.type == HB_OP_REG ? is_plain_gpr_reg_operand(&cur->src2)
                                                          : cur->src2.type == HB_OP_IMM) &&
                             ((prev->op == HB_IR_ADD) == (cur->op == HB_IR_ADC));
                if (sootv) HB_PROBE_HIT(&pr_adc_perepis);
            }
        }
        /* ★ СНЯТИЕ МЁРТВОЙ ЗАПИСИ ЛЕНИВЫХ ФЛАГОВ (итерация 160). Решение принято ПЕРВЫМ
         * проходом по выпущенному коду, где виден и обрыв (ветвление), и вызов помощника, —
         * в отличие от живости, которая решает по IR и потому вынуждена считать барьером
         * всякую команду, способную отказать (дефект итерации 132). */
        if (deadlazy_marked_at(i)) g_lazy_flags_skip = 1;
        /* ★★★ 06.09.2026, лейн ПРИБОРЫ-3 — ЭТОТ ПРИБОР СЛУЖИЛ КРИТЕРИЕМ ЖИВОСТИ,
         * а его ноль означал ТРИ разные вещи сразу, и различить их было нечем:
         *
         *   1. гейт MACRUNNER_HB_FLAG_LIVENESS выключен (умолчание 0) — счётчик
         *      g_flagliv_seen не растёт вовсе, потому что стоит ВНУТРИ условия;
         *   2. команд с записью флагов не транслировалось;
         *   3. они транслировались, но их меньше периода печати (умолчание 200 000) —
         *      ровно этот случай 09.08 сделал замер −3.82 % недействительным при
         *      полностью исправной оптимизации, о чём памятка ниже.
         *
         * Порядок вычисления сохранён В ТОЧНОСТИ (гейт первым, короткое замыкание на
         * месте): учёт добавлен ВОКРУГ него, а не вместо. Два прибора, и каждый ноль
         * теперь называет свою причину:
         *
         *   pr_flagliv_gejt   looked>0, hits=0  -> ГЕЙТ ВЫКЛЮЧЕН (не «нечего снимать»)
         *   pr_flagliv_snyato looked>0, hits=0  -> гейт открыт, снимать нечего (честный ноль)
         *
         * Итог печатается переписью НА ВЫХОДЕ и потому не зависит от периода: случай 3
         * закрыт устройством. Цена — одно атомарное сложение на ТРАНСЛИРОВАННУЮ команду
         * (кодогенерация, не выпущенный код). */
        HB_PROBE_LOOKED(&pr_flagliv_gejt);
        if (flag_liveness_enabled()) HB_PROBE_HIT(&pr_flagliv_gejt);
        if (flag_liveness_enabled() && flags_written_mask(&block->instrs[i])) {
            HB_PROBE_LOOKED(&pr_flagliv_snyato);
            g_flagliv_seen++;
            if (lazy_flags_dead_at_lim(block, i, instr_limit) &&
                (i + 1 >= instr_limit || !flags_written_mask(&block->instrs[i + 1]) ||
                 lazy_flags_dead_at_lim(block, i + 1, instr_limit))) {
                g_lazy_flags_skip = 1;
                g_flagliv_skipped++;
                HB_PROBE_HIT(&pr_flagliv_snyato);
            }
            /* Заметка пары «производитель + Jcc»: спрашиваем ПРЕЕМНИКОВ перехода, а не
             * сам переход. Действует только внутри сращивающих эмиттеров.
             *
             * ★★★ ОТДЕЛЬНЫЙ ГЕЙТ И УМОЛЧАНИЕ 0 — ПОТОМУ ЧТО ОРАКУЛ ЭТОТ КЛАСС НЕ ПРОВЕРЯЕТ.
             * Единственная форма, где снятие сегодня доходит до выпуска, — сращённая пара
             * E/NE, чья ЦЕЛЬ ведёт НАЗАД внутрь той же единицы. Такие случаи стенд
             * исполнить не может (`exec_result:0:-18` на всех девяти, на ОБЕИХ руках):
             * блок кончается переходом, а продолжить с середины окна стенд не умеет.
             * По правилу проекта «безопасность, не доказанная оракулом, считается
             * недоказанной» гейт остаётся ВЫКЛЮЧЕННЫМ, а число названо отдельно. */
            if (!g_lazy_flags_skip && flag_liveness_cfg_enabled() &&
                hb_jit_gate_flag( HB_GATE_HB_FLAG_LIVENESS_PAIR, 0) &&
                lazy_note_dead_for_fused_pair(block, i, instr_limit))
                g_lazy_pair_dead = 1;
            /* MacRunner 2026-08-09 — период печати сделан переменной.
             *
             * Счётчик считает ТРАНСЛИРОВАННЫЕ команды с записью флагов, а не исполненные.
             * За 130-секундную загрузку HK их набирается меньше 200 000, поэтому свидетель
             * не срабатывал ни разу, и замер −3.82% пришлось объявить недействительным при
             * полностью исправной оптимизации. Умолчание оставлено прежним. */
            {
                static int flagliv_period = -1;
                if (flagliv_period < 0) {
                    const char* pe = hb_gate( HB_GATE_HB_FLAG_LIVENESS_PERIOD );
                    flagliv_period = (pe && *pe) ? atoi(pe) : 200000;
                    if (flagliv_period <= 0) flagliv_period = 200000;
                }
                if ((g_flagliv_seen % (uint64_t)flagliv_period) == 0)
                    fprintf(stderr, "macrunner-hb-flag-liveness: команд-с-флагами=%llu пропущено=%llu (%.1f%%)\n",
                            (unsigned long long)g_flagliv_seen, (unsigned long long)g_flagliv_skipped,
                            100.0 * (double)g_flagliv_skipped / (double)g_flagliv_seen);
            }
        }
        /* Host half of the FEX-style (host offset -> guest RIP) map: where this guest
         * instruction's code begins. The guest half is block->instrs[i].guest_addr, which the IR
         * already carries, so the pair is complete without emitting anything into the code
         * stream. Fusions that consume several instructions record only the first, which is
         * correct: the fault lands inside the fused sequence and the guest position that matters
         * is where that sequence started.
         *
         * The instruction index is recorded EXPLICITLY alongside the offset rather than being
         * inferred from the entry number. Those two are equal only in a block where no fusion
         * fired: every fusion advances `i` past instructions that get no entry, so the entry
         * counter runs behind `i` from that point on. Reading block->instrs[] by entry number
         * therefore returns a different instruction's guest address -- silently, and in the
         * common case, since CMP/Jcc is fused. See hb_codegen.h. */
        if (out->host_off_count < HB_CODEGEN_MAX_HOST_OFF) {
            out->host_instr[out->host_off_count] = (uint16_t)i;
            out->host_off[out->host_off_count++] = (uint32_t)out->size;
        } else
            out->host_off_overflow = true;

        /* ★★★★★★★ 05.09.2026 — БЛОКИРУЮЩАЯ RMW УХОДИТ В НЕДЕЛИМОГО ПОМОЩНИКА.
         *
         * Разбор механизма — у `hb_jit_atomic_rmw`. Здесь важно ГДЕ: до всякого
         * сращивания. Сращивание блокирующей операции с соседкой сняло бы и барьеры, и
         * перепись, и эту развилку разом; сегодня оно не срабатывает лишь потому, что
         * `emit_arith_rmw_dead_flags_test_jcc` упирается в предикат прямой записи, а тот
         * выключен. Это не свойство блокирующей операции, а совпадение настроек — то
         * есть леса. Развилка поставлена выше их всех, и вопрос закрыт по построению.
         *
         * CMPXCHG/CMPXCHG8B/XCHG/XADD сюда НЕ входят: они и так уходят в того же
         * помощника из `codegen_instr`, и стенд даёт им 0 потерь. Их обкладка барьерами
         * остаётся прежней побайтово.
         *
         * Перепись выпускается ЗДЕСЬ теми же тремя командами и по тому же правилу
         * «первая команда IR гостевого адреса», поэтому числа частоты сравнимы с
         * замером 05.09 до правки. */
        /* ★★★ СНАЧАЛА LSE, ПОТОМ ПОМОЩНИК — И ВОТ ПОЧЕМУ ЭТО НЕ ОСЛАБЛЕНИЕ (07.09.2026).
         *
         * Развилка версии 29 ниже уводит ВСЮ строчную семью блокирующих RMW в неделимого
         * помощника, потому что прежний СТРОЧНЫЙ выпуск был НЕатомарен и терял приращения.
         * Но она стоит ВЫШЕ ветви LSE, а значит с 05.09 ветвь LSE недостижима: гейт
         * `MACRUNNER_HB_LSE_ATOMICS=1` не менял выпуск НИ НА ОДНО СЛОВО. Проверено
         * числом — на корпусе из 680 блокирующих операций при гейте 0 и 1 выпускается
         * ровно 48 920 слов, то есть одно и то же.
         *
         * Это второй раз для одного и того же кода: 19.08 у `hb_arm64_codegen_instr`
         * нашли НОЛЬ вызовов и проверку перенесли сюда, в цикл блока; теперь её накрыла
         * развилка версии 29. Класс тот же — «гейт есть, кода в исполнении нет».
         *
         * ПОЧЕМУ LSE МОЖНО СТАВИТЬ ВЫШЕ. Возражение версии 29 было к НЕАТОМАРНОСТИ
         * строчного выпуска, а не к строчному выпуску как таковому. `LDADDAL`/`LDCLRAL`/
         * `LDSETAL`/`LDEORAL` — ОДНА команда, неделимая по устройству, с упорядочиванием
         * acquire+release. Приращения ей терять нечем. Помощник же стоит вызова, упаковки
         * аргументов и общей блокировки — то есть здесь LSE не «дешевле помощника», а
         * снимает саму статью расхода.
         *
         * ГРАНИЦА: только ADD/SUB/AND/OR/XOR и только 32/64 бита — остальная семья
         * (ADC/SBB/NEG/NOT/BTS/BTR/BTC, ширины 8/16) одной командой LSE не выражается и
         * уходит к помощнику по-прежнему. Эмиттеры сами возвращают false, и тогда
         * управление проваливается в развилку ниже без изменений.
         *
         * УМОЛЧАНИЕ ГЕЙТА ОСТАВЛЕНО 0: при выключенном гейте выпуск байт в байт прежний. */
        if (hb_lse_atomics_enabled() && hb_lock_rmw_inline_family(&block->instrs[i]) &&
            !hb_lock_rmw_uses_atomic_helper(&block->instrs[i])) {
            const hb_ir_instr_t* ls_instr = &block->instrs[i];
            bool vzyato = (ls_instr->op == HB_IR_SUB)
                              ? emit_locked_sub_atomic(out, ls_instr)
                              : emit_locked_rmw_lse(out, ls_instr);
            if (vzyato) {
                if (i == 0 || block->instrs[i - 1].guest_addr != ls_instr->guest_addr) {
                    emit_lock_census(out, lock_census_slot_for(ls_instr));
                    lock_census_periodicheski();
                }
                continue;
            }
        }
        if (hb_lock_rmw_inline_family(&block->instrs[i]) &&
            !hb_lock_rmw_uses_atomic_helper(&block->instrs[i])) {
            const hb_ir_instr_t* at_instr = &block->instrs[i];
            hb_result_t at_r = emit_atomic_ir_helper(out, at_instr);
            if (at_r != HB_OK) return at_r;
            if (i == 0 || block->instrs[i - 1].guest_addr != at_instr->guest_addr) {
                emit_lock_census(out, lock_census_slot_for(at_instr));
                lock_census_periodicheski();
            }
            continue;
        }
        if (i + 2 < instr_limit &&
            emit_arith_rmw_dead_flags_test_jcc(out, &block->instrs[i], &block->instrs[i + 1],
                                               &block->instrs[i + 2])) {
            i += 2;
            continue;
        }
        if (i + 3 < instr_limit &&
            emit_stack_spill_push_sub_prologue(out, &block->instrs[i], &block->instrs[i + 1],
                                               &block->instrs[i + 2], &block->instrs[i + 3])) {
            i += 3;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_xfg_dispatch_call_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 2 < instr_limit &&
            emit_store_imm_mov_lea_same_base(out, &block->instrs[i], &block->instrs[i + 1],
                                             &block->instrs[i + 2])) {
            i += 2;
            continue;
        }
        if (i + 2 < instr_limit &&
            emit_scalar_flags_setcc_sequence(out, &block->instrs[i], &block->instrs[i + 1],
                                             &block->instrs[i + 2])) {
            i += 2;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_scalar_flags_setcc_sequence(out, &block->instrs[i], NULL, &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_mov_lea_same_base_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_xmm_load_store_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_scalar_load_store_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_adjacent_mem64_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_mem_reg_flags_jcc_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_mem_imm_flags_jcc_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_test_same_reg_jcc_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        /* Full-condition CMP/SUB + Jcc goes first: it takes the signed and unsigned families
         * that emit_scalar_flags_jcc_pair rejects (it only handles E/NE). Gated OFF by default;
         * when the gate is off this call returns immediately and the old path is unchanged. */
        if (i + 1 < instr_limit &&
            emit_cmp_sub_jcc_native(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        if (i + 1 < instr_limit &&
            emit_scalar_flags_jcc_pair(out, &block->instrs[i], &block->instrs[i + 1])) {
            i++;
            continue;
        }
        /* MacRunner Lane A (2026-06-17): x86 LOCK-prefixed RMW (lock or/and/add/...) acts as a
         * full memory barrier.  block_has_atomic_ir only routes CMPXCHG/XCHG/XADD through the
         * DMB-bracketed atomic helper, so bracket every other lock-flagged op with DMB ISH here
         * — Mono hazard-pointer loops (`lock or [rsp],r`) livelock on ARM64 without it. */
        const hb_ir_instr_t* lk_instr = &block->instrs[i];
        /* MacRunner 19.08, лейн ЛЕСТНИЦА итерация 2545 по приказу 208 (находка лейна ЧТЕЦ).
         * Проверка LSE жила в hb_arm64_codegen_instr, у которой НОЛЬ вызовов — сверено
         * двумя способами независимо: по исходникам (3 упоминания на 4 деревьях, все три
         * не вызовы: объявление hb_codegen.h:148, комментарий hb_interpreter.c:3636,
         * определение :13416) и по объектникам (nm: T есть, U нет ни одной).
         * Поэтому включение MACRUNNER_HB_LSE_ATOMICS не давало НИЧЕГО, а исполнялась
         * обкладка dmb ish — та самая, что комментарий :270 называет неверной: барьер
         * упорядочивает, но неделимости не даёт, и одновременные приращения теряются.
         * Переношу проверку сюда, где is_locked уже под рукой.
         * ★ УМОЛЧАНИЕ ГЕЙТА ОСТАВЛЕНО 0: при нынешних настройках выпуск байт-в-байт
         * прежний. Менять умолчание без прогона нельзя, а прогоны заблокированы (2540). */
        /* Считать ли ЭТУ команду IR в перепись — разбор ниже, у самого счёта. */
        const bool lk_schitat =
            lk_instr->is_locked && !hb_lock_rmw_uses_atomic_helper(lk_instr) &&
            (i == 0 || block->instrs[i - 1].guest_addr != lk_instr->guest_addr);
        if (lk_instr->is_locked && hb_lse_atomics_enabled()) {
            /* ТОЛЬКО continue, без i++: цикл на :13800 сам делает i++. Соседние ветви
             * (emit_cmp_sub_jcc_native, emit_scalar_flags_jcc_pair) пишут i++ потому,
             * что СЛИВАЮТ ДВЕ команды; наша съедает одну. С лишним i++ следующая
             * команда блока молча не выпускалась бы. */
            if (lk_instr->op == HB_IR_SUB) {
                if (emit_locked_sub_atomic(out, lk_instr)) {
                    if (lk_schitat) emit_lock_census(out, HB_LKC_SUB);
                    continue;
                }
            } else if (emit_locked_rmw_lse(out, lk_instr)) {
                if (lk_schitat) { emit_lock_census(out, lock_census_slot_for(lk_instr));
                          lock_census_periodicheski(); }
                continue;
            }
        }
        if (lk_instr->is_locked) emit_dmb_ish(out);
        hb_result_t r = codegen_instr(out, lk_instr);
        if (r != HB_OK) {
            /* Выпуск отказал — блока не будет, и переписи прямых единиц он не
             * принадлежит. Снимаем ту единицу, что записали на входе: иначе
             * «без_pc» считало бы отказы выпуска дефектом записи pc, то есть
             * прибор врал бы в ту же сторону, от которой он и заведён. */
            if (codegen_block_is_straight(block))
                __atomic_sub_fetch(&g_cg_straight_units, 1, __ATOMIC_RELAXED);
            return r;
        }
        if (lk_instr->is_locked) emit_dmb_ish(out);
        /* Перепись — ПОСЛЕ выпуска и ПОСЛЕ замыкающего барьера: до сюда управление
         * доходит только когда операция действительно исполнена. X16 к этому месту
         * расходный, живых значений в нём нет.
         *
         * CMPXCHG/CMPXCHG8B/XCHG/XADD сюда НЕ попадают: они безусловно уходят в
         * помощника (codegen_instr:11607), и там счёт ведётся на C — даром, вызов и
         * так есть. Иначе одна операция считалась бы дважды.
         *
         * ★ СЧЁТ ПО ГОСТЕВОЙ КОМАНДЕ, А НЕ ПО КОМАНДЕ IR. Лифтер помечает `is_locked`
         * ВСЕ команды IR, порождённые одной операцией с префиксом (hb_lift_x86.c:2324),
         * а их бывает несколько. Прибор без этой проверки завышал бы частоту в разы —
         * ровно тот класс, что уже стоил проекту дня («кратная форма прибора завысила
         * цену вчетверо»). Сверка: у соседей по блоку guest_addr различны. */
        if (lk_schitat) emit_lock_census(out, lock_census_slot_for(lk_instr));
    }
    if (out && out->size >= emit_size_before) {
        g_emit_bytes += (uint64_t)(out->size - emit_size_before);
        if (g_emit_ir && (g_emit_ir % 200000) == 0)
            fprintf(stderr, "macrunner-hb-code-density: команд-IR=%llu байт=%llu на-команду=%.2f\n",
                    (unsigned long long)g_emit_ir, (unsigned long long)g_emit_bytes,
                    (double)g_emit_bytes / (double)g_emit_ir);
    } }
    /* ЕДИНИЦА, часть Б: дошивка внутренних переходов.
     *
     * Цель могла не получить собственного смещения — цикл умеет сращивать пары команд, и
     * тогда вторая половина не выпускается отдельно. Гадать нельзя, поэтому на такой случай
     * выпускается ЗАГЛУШКА: записать ctx->pc = цель и уйти в эпилог, то есть прежнее
     * поведение. Правка остаётся верной при любом сращивании. */
    /* ★★★★★ MacRunner 2026-08-24 — КОНЕЦ СЛИТОЙ ЕДИНИЦЫ ОБЯЗАН ЗАПИСАТЬ pc.
     *
     * До слияния запись pc в конце блока была НЕ НУЖНА, и её тут нет: обрыв выпуска на
     * первом переходе (codegen_instr_limit_before_fallthrough) гарантировал, что последняя
     * выпущенная команда — переход, а он pc пишет сам.
     *
     * Слитая единица это допущение ломает: она может кончиться обычной командой. Тогда pc
     * остаётся прежним, диспетчер входит в ТОТ ЖЕ блок снова и считает его второй раз —
     * отсюда неверный ответ стенда при любом MERGE_MAX >= 1, при том что продление лифтером
     * само по себе безопасно (проверено: с MERGE_NO_EXTEND=1 ответ верен).
     *
     * Пишем адрес следующей гостевой команды за последней выпущенной. */
    /* ★★★★★★★ MacRunner 05.09.2026 — ЗАПИСЬ pc СТАЛА БЕЗУСЛОВНОЙ.
     *
     * Выше записано: «до слияния запись pc в конце блока была НЕ НУЖНА», потому что
     * обрыв выпуска на первом переходе якобы гарантирует переход последней командой.
     * Эта гарантия ЛОЖНА и без слияния: если в единице НЕТ перехода ВОВСЕ (лифтер
     * оборвал её по своей длине посреди прямого участка), то `codegen_instr_limit_before_fallthrough`
     * возвращает `instr_count`, последняя выпущенная команда НЕ переход, и pc не пишет НИКТО.
     *
     * Почему это не стреляло раньше: диспетчер чинил это в C — ветвь
     * «Sequential block end — stop»: `ctx->pc = last->guest_addr + last->guest_len;`
     * (hb_runtime.c). СЦЕПЛЕНИЕ ИМЕННО ЭТУ СТРОКУ И СНИМАЕТ: цепочка не возвращается
     * в диспетчер между блоками. Цель ребра без перехода исполняется, оставляет pc на
     * СОБСТВЕННОМ входе — и диспетчер ИСПОЛНЯЕТ ЕЁ ВТОРОЙ РАЗ.
     *
     * ИЗМЕРЕНО на Hollow Knight (прибор slotprobe, 05.09.2026): единица
     * mono-2.0-bdwgc.dll+0x46ab14 — 51 команда прямого кода без единого перехода,
     * дописывающая 4 байта к курсору выпуска Mono. Со сцеплением она исполнялась
     * ДВАЖДЫ, Mono насчитывал 14 выпущенных байт вместо 10 и ронял себя утверждением
     * `(code - cfg->native_code - offset) <= max_len` на команде i8const.
     *
     * Запись безусловная, а не под гейтом слияния: выпущенная единица обязана
     * оставлять гостевой pc ТОЧНЫМ САМА, а не полагаться на то, что за ней обязательно
     * выполнится какой-то код на C. Это тот же инвариант, что держат эталоны (QEMU
     * обновляет cpu_pc на выходе КАЖДОГО TB), и без него сцепление неверно ПО ПОСТРОЕНИЮ.
     *
     * Место выбрано то же, где стояла прежняя запись слияния: перед ФИНАЛЬНЫМ
     * эпилогом. Ранние выходы (отказ помощника, срок, ошибка доступа) выпускают
     * СВОЙ эпилог по месту (`emit_epilogue_mid_block`) и сюда не попадают, то есть точный
     * pc места отказа не затирается. x20 не принадлежит ни одному банку закрепления
     * (x25-x28 и x11-x15), а выгрузка грязных идёт внутри эпилога, то есть ПОСЛЕ. */
    /* ГЕЙТ СНЯТ 05.09.2026 — лечение доказано и стало БЕЗУСЛОВНЫМ.
     * Рычаг MACRUNNER_HB_TAILPC служил ровно одному: развести две половины правки
     * на одном двоичном файле. Замер (свои хранилища перевода на руку, иначе вторая
     * рука поднимает блоки первой): TAILPC=0 — утверждение Mono 1, журнал 62 685
     * строк, ступень 1; TAILPC=1 — утверждение 0, журнал 151 099 строк, ступень 9. */
    /* ОДНА ТОЧКА НА ОБЕ ВЕТВИ — та же, что зовут быстрые пути выше. Пояснение,
     * почему укладка компактная, и перепись прямых единиц — у самой функции. */
    codegen_emit_tail_pc_if_needed(out, block, instr_limit);
    if (g_cg_merge_block == block && out) {
        /* ★★★★★ MacRunner 2026-08-24 — ОСНОВНОЙ ПУТЬ НЕ ДОЛЖЕН ПРОВАЛИВАТЬСЯ В ЗАГЛУШКУ.
         *
         * Заглушки недостижимых целей выпускаются ПОСЛЕ основного кода. Перехода перед ними
         * не было, поэтому дойдя до конца блока исполнение сваливалось прямо в первую из
         * них — и записывало ctx->pc на ЧУЖУЮ цель. Отказ выглядел как EXEC_FAULT на CALL:
         * управление уходило по адресу, который к этому месту отношения не имеет.
         *
         * Эпилог перед заглушками закрывает основной путь. Он же остаётся в конце функции —
         * второй недостижим и стоит четыре слова на блок только там, где заглушки есть. */
        /* ★ СТОРОЖ: команда-переход ВНУТРИ предела, чей выпуск не зарегистрирован,
         * означает сращивание — оно вернуло управление диспетчеру, а за ним лежит хвост. */
        if (!g_cg_merge_force_limit) {
            size_t q, lim_g = codegen_instr_limit_before_fallthrough(block);
            for (q = 0; q + 1 < lim_g && q < CG_MERGE_MAX_INSTR && q < block->instr_count; q++) {
                if (!codegen_is_control_transfer_op(block->instrs[q].op)) continue;
                if (g_cg_merge_off[q] != (size_t)-1) continue;
                /* ★ ВТОРОЙ ФАКТ, А НЕ ТОТ ЖЕ (лейн ФЛАГИ-2). Переход, поглощённый
                 * сращиванием и завершённый ВНУТРЕННИМ РЕБРОМ, корректен: управление
                 * передано на host-метку, `ctx->pc` не писан и не нужен. Сторож обязан
                 * его пропустить — но `g_cg_merge_off[q]` остаётся −1, потому что
                 * НЕЗАВИСИМЫЙ ВХОД по этому гостевому адресу по-прежнему запрещён. */
                if (g_cg_merge_covered[q]) continue;
                g_cg_merge_need_limit = q + 1;
                __atomic_add_fetch(&g_cg_merge_guard_hits, 1, __ATOMIC_RELAXED);
                break;
            }
        }
        bool mg_guard_emitted = false;
        /* Заплата не достала ни цели, ни заглушки, а повтор с обрезанным пределом уже
         * был: выпустить корректный код нечем. Отказ ЧЕСТНЫЙ — блок уйдёт запасным
         * путём, а не исполнится с переходом по усечённому смещению. */
        bool mg_fix_fatal = false;
        /* ★ ЕДИНИЦА, итерация 18 — РАЗВЕДЕНИЕ ДВУХ ПОДОЗРЕВАЕМЫХ.
         * `MACRUNNER_HB_MERGE_NO_INNER_JUMP=1` оставляет ХВОСТ выпущенным, но запрещает
         * прыжок ВНУТРЬ: заплата уходит в заглушку с записью ctx->pc и возвратом в
         * диспетчер — ровно так же, как без слияния. Заглушка уже написана (ветка
         * «цель не найдена» ниже), поэтому новый код не нужен.
         *   падение УХОДИТ -> виноват ВХОД В СЕРЕДИНУ (точка схода)
         *   падение ОСТАЁТСЯ -> виноват сам выпуск хвоста */
        static int no_inner = -1;
        if (no_inner < 0) { const char* v = hb_gate( HB_GATE_HB_MERGE_NO_INNER_JUMP );
            no_inner = (v && *v && *v != '0') ? 1 : 0;
            fprintf(stderr, "macrunner-gate: MACRUNNER_HB_MERGE_NO_INNER_JUMP=%d\n", no_inner);
            fflush(stderr); }
        for (size_t k = 0; k < g_cg_merge_fix_n; k++) {
            size_t j = 0, dest = (size_t)-1;
            const cg_merge_fix_t* f = &g_cg_merge_fix[k];
            const char* ishod;
            if (!no_inner && cg_merge_target_index(block, f->target, &j) &&
                j < CG_MERGE_MAX_INSTR) {
                if (g_cg_merge_off[j] != (size_t)-1) dest = g_cg_merge_off[j];
                /* ★ ОТРИЦАТЕЛЬНЫЙ КОНТРОЛЬ: вернуть подмену двух фактов. Вход по адресу
                 * ПОГЛОЩЁННОГО Jcc ведёт в начало сращённой пары — то есть в предикат,
                 * посчитанный для ДРУГОГО предшественника. Оракул обязан покраснеть. */
                else if (g_cg_merge_covered[j]) {
                    __atomic_add_fetch(&g_cg_edge_target_is_fused, 1, __ATOMIC_RELAXED);
                    if (cg_edge_entry_fused_test() && g_cg_merge_pair_off[j] != (size_t)-1)
                        dest = g_cg_merge_pair_off[j];
                }
            }
            if (dest != (size_t)-1 && cg_fix_patch(out, f, dest)) {
                ishod = "vnutr";
                cg_fix_selfcheck(out, f, dest);
                __atomic_add_fetch(&g_cg_edge_resolved, 1, __ATOMIC_RELAXED);
            } else {
                /* ★ ЗАПАСНОЙ ПУТЬ — ЗАГЛУШКА, А НЕ УСЕЧЁННОЕ СМЕЩЕНИЕ. Цель вне единицы,
                 * не выпущена или форма её НЕ ДОСТАЁТ: пишем pc и уходим в диспетчер —
                 * ровно то, что делал бы выпуск без слияния. */
                if (!mg_guard_emitted) { emit_epilogue(out); mg_guard_emitted = true; }
                ishod = "stub";
                __atomic_add_fetch(&g_cg_edge_stub, 1, __ATOMIC_RELAXED);
                if (!cg_fix_patch_stub(out, f, out->size)) {
                    /* ★★★ НЕДОСТИЖИМА ДАЖЕ ЗАГЛУШКА. Единственный честный выход —
                     * ПЕРЕВЕСТИ ЗАНОВО с пределом, обрезанным на этом переходе: тогда
                     * пара выпустит свой обычный ВНЕШНИЙ хвост. Усечь смещение здесь
                     * значило бы отправить управление по чужому адресу молча. Буфер
                     * этого прохода повтор выбрасывает целиком, поэтому дописывать
                     * заглушку незачем. */
                    ishod = "predel";
                    __atomic_add_fetch(&g_cg_edge_relimit, 1, __ATOMIC_RELAXED);
                    if (!g_cg_merge_force_limit && f->instr_i + 1 > g_cg_merge_need_limit)
                        g_cg_merge_need_limit = f->instr_i + 1;
                    else
                        mg_fix_fatal = true;   /* повтор уже был — честный отказ выпуска */
                    continue;
                }
                emit_mov_imm64(out, 20, f->target);
                emit_str_x(out, 20, 19, (uint32_t)offsetof(hb_context_t, pc));
                emit_epilogue(out);
            }
            /* ★ АДРЕСНЫЙ РЕЕСТР РЁБЕР (MACRUNNER_HB_MERGE_LEDGER=N, первые N строк).
             * Различает ровно то, что раньше сливалось в одно число: САЙТ, выбранную
             * ФОРМУ, смещение заплаты, цель и ИСХОД разрешения. Без него «ноль слов»
             * означало бы сразу и «анализ не увидел», и «сращивание отказало», и
             * «ребро ушло в заглушку». Латиницей — вывод ищут в журнале через strings. */
            if (cg_edge_ledger()) {
                static unsigned long ledger_n;
                if (ledger_n < (unsigned long)cg_edge_ledger()) {
                    static const char* imya[4] = { "b.cond", "cbz", "tbz", "b" };
                    ledger_n++;
                    fprintf(stderr,
                            "macrunner-edinica-rebro: blok=0x%llx i=%zu forma=%s pol=%u "
                            "reg=%u bit=%u pos=%zu cel=0x%llx -> %s\n",
                            (unsigned long long)block->guest_addr, f->instr_i,
                            imya[f->kind & 3], (unsigned)f->cond, (unsigned)f->reg,
                            (unsigned)f->bit, f->pos, (unsigned long long)f->target, ishod);
                    fflush(stderr);
                }
            }
        }
        /* ★★★ ЕДИНИЦА, итерация 12 — ПЕЧАТЬ ВЫПУСКА СЛИТОЙ ЕДИНИЦЫ.
         *
         * Зачем именно печать, а не кеш: замер 11 показал, что в кеше упавшей руки НЕТ
         * НИ ОДНОЙ слитой единицы (66 записей, все побайтно как у рабочей руки) — падение
         * наступает раньше записи на диск. Сличать выпуск можно только из прогона.
         *
         * Печатается только НАСТОЯЩАЯ слитая единица (есть хоть одна внутренняя заплата),
         * первые MACRUNNER_HB_MERGE_DUMP штук. Латиницей: кириллицу рвёт strings, а этот
         * вывод придётся искать в журнале упавшего прогона. */
        {
            static int dump_n = -1;
            static unsigned long dumped;
            if (dump_n < 0) {
                const char* v = hb_gate( HB_GATE_HB_MERGE_DUMP );
                dump_n = (v && *v) ? atoi(v) : 0;
                if (dump_n < 0) dump_n = 0;
            }
            /* Условие печати: выпуск УШЁЛ ЗА ПЕРВЫЙ переход — что бы его туда ни увело.
             * Прежнее условие (есть внутренняя заплата) дало НОЛЬ строк на падающем
             * прогоне: значит слитых единиц с внутренним b.cond до падения не выпускалось,
             * и виноват не он. Считаем переходы среди ВЫПУЩЕННЫХ команд. */
            size_t lim0 = codegen_instr_limit_before_fallthrough(block), tr = 0, q;
            for (q = 0; q < lim0 && q < block->instr_count; q++)
                if (codegen_is_control_transfer_op(block->instrs[q].op)) tr++;
            if (dump_n && (tr > 1 || dump_n >= 100) && dumped < (unsigned long)dump_n) {
                size_t k, lim = lim0;
                dumped++;
                fprintf(stderr,
                        "macrunner-edinica-dump #%lu: guest=0x%llx instr_count=%zu limit=%zu "
                        "zaplat=%zu bytes=%zu\n",
                        dumped, (unsigned long long)block->guest_addr,
                        block->instr_count, lim, g_cg_merge_fix_n, out->size);
                /* dump_n >= 1000 — КОМПАКТНЫЙ режим: только заголовки. Нужен, чтобы
                 * накрыть ВСЕ единицы прогона (их сотни) и найти ту, чей гостевой
                 * диапазон содержит адрес отказа. Полная выгрузка столько не выдержит. */
                if (dump_n >= 1000) { fflush(stderr); goto ed_dump_done; }
                for (k = 0; k < block->instr_count && k < 40; k++) {
                    /* ЧИСЛОВОЕ смещение выпуска, а не «est/NET»: без него смещение
                     * невыпущенной проверки отказа не привязать к команде. */
                    size_t off = (k < CG_MERGE_MAX_INSTR) ? g_cg_merge_off[k] : (size_t)-1;
                    fprintf(stderr, "   i%02zu op=%d guest=0x%llx len=%u off=%lld\n",
                            k, (int)block->instrs[k].op,
                            (unsigned long long)block->instrs[k].guest_addr,
                            (unsigned)block->instrs[k].guest_len,
                            (off == (size_t)-1) ? -1LL : (long long)off);
                }
                for (k = 0; k < g_cg_merge_fix_n && k < 8; k++) {
                    size_t j = 0; const char* rez = "NE-NASHLI";
                    if (cg_merge_target_index(block, g_cg_merge_fix[k].target, &j) &&
                        j < CG_MERGE_MAX_INSTR && g_cg_merge_off[j] != (size_t)-1) rez = "vnutr";
                    fprintf(stderr, "   zaplata%zu pos=%zu cond=%d target=0x%llx -> %s i%zu\n",
                            k, g_cg_merge_fix[k].pos, g_cg_merge_fix[k].cond,
                            (unsigned long long)g_cg_merge_fix[k].target, rez, j);
                }
                for (k = 0; k + 4 <= out->size && k < 3072; k += 4) {
                    unsigned w;
                    memcpy(&w, out->code + k, 4);
                    if ((k & 31u) == 0) fprintf(stderr, "   %04zx:", k);
                    fprintf(stderr, " %08x", w);
                    if ((k & 31u) == 28) fprintf(stderr, "\n");
                }
                fprintf(stderr, "\n");
                fflush(stderr);
ed_dump_done: ;
            }
        }
        g_cg_merge_block = NULL;
        g_cg_merge_fix_n = 0;
        cg_edge_reset();
        if (mg_fix_fatal) return HB_ERR_JIT_FAILED;
    }
    g_cg_want_slot2 = 1;
    emit_epilogue(out);
    g_cg_want_slot2 = 0;
    /* ★ ОТПЕЧАТОК ВЫПУСКА — дешёвый отсев мёртвых гейтов.
     *
     * Мерить каждый рычаг на игре — по два прогона, десять часов на сто сорок штук. Но
     * рычаг, который не меняет ВЫПУЩЕННЫЙ КОД, мерить незачем вовсе. Сумма длин и свёртка
     * байтов по всем блокам прогона дают такой признак за секунды и детерминированно, в
     * отличие от файла кеша (его хеш плывёт от прогона к прогону: 8860 против 8624 байт на
     * двух одинаковых запусках). */
    {
        extern unsigned long long g_cg_emit_bytes, g_cg_emit_sum, g_cg_emit_blocks;
        size_t i2;
        g_cg_emit_blocks++;
        g_cg_emit_bytes += out->size;
        for (i2 = 0; i2 < out->size; i2++)
            g_cg_emit_sum = g_cg_emit_sum * 1099511628211ull ^ (unsigned long long)out->code[i2];
    }
    return HB_OK;
}

hb_result_t hb_arm64_codegen_block(hb_arm64_codegen_t* cg, const hb_ir_block_t* block, hb_codegen_buffer_t* out) {
    return hb_arm64_codegen_block_with_cfg(cg, block, NULL, out);
}

hb_result_t hb_arm64_codegen_func(hb_arm64_codegen_t* cg, const hb_ir_func_t* func, hb_codegen_buffer_t* out) {
    if (!func || !func->cfg || !out) return HB_ERR_INVALID_ARG;
    if (cg && cg->ctx) out->arch = cg->ctx->arch;
    for (size_t i = 0; i < func->cfg->block_count; i++) {
        hb_result_t r = hb_arm64_codegen_block(cg, func->cfg->blocks[i], out);
        if (r != HB_OK) return r;
    }
    return HB_OK;
}
